output_text:
[
  {
    "id": "obtain_cart",
    "text": "The shopper is obliged to acquire a cart at some point during the trip.",
    "abstraction": {},
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "hasCart"
    }
  },
  {
    "id": "use_cart_bay",
    "text": "The shopper is obliged to interact at the cart bay before completing the trip.",
    "abstraction": {},
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": {
        "and": [
          "at(1,7)",
          "INTERACT"
        ]
      }
    }
  },
  {
    "id": "exit_with_cart",
    "text": "The shopper is obliged to leave the store while still having a cart.",
    "abstraction": {},
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": {
        "and": [
          "EXIT",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "no_exit_without_cart",
    "text": "The shopper is prohibited from exiting the store without a cart.",
    "abstraction": {},
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "no_cart_in_item_aisle",
    "text": "The shopper is prohibited from bringing a cart into the narrow item aisle at cells (3,1) and (3,2).",
    "abstraction": {},
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          {
            "or": [
              "at(3,1)",
              "at(3,2)"
            ]
          }
        ]
      }
    }
  },
  {
    "id": "no_cart_north_from_parking",
    "text": "The shopper is prohibited from moving north from cell (3,3) while holding a cart.",
    "abstraction": {},
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "at(3,3)",
          "hasCart",
          "N"
        ]
      }
    }
  },
  {
    "id": "return_to_cart_after_item",
    "text": "After interacting with the item location at (3,1), the shopper is obliged to regain a cart.",
    "abstraction": {},
    "norm": {
      "type": "obligation",
      "trigger": {
        "and": [
          "at(3,1)",
          "INTERACT"
        ]
      },
      "discharge": "hasCart"
    }
  },
  {
    "id": "cart_free_item_interaction",
    "text": "The shopper is prohibited from interacting at cell (3,1) while holding a cart.",
    "abstraction": {},
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "at(3,1)",
          "INTERACT",
          "hasCart"
        ]
      }
    }
  }
]
